<template><section class="panel" data-testid="sequence-candidates"><h3>Complete native candidate ranking</h3><p class="muted">Priority records for verification. Evidence coverage is explicit; scores are not validated functional probabilities.</p><div class="sequence-viz-controls"><label>Native module<select v-model="module" class="input"><option v-for="m in modules" :key="m" :value="m">{{ m }}</option></select></label><label>Evidence coverage<select v-model="coverage" class="input"><option value="all">All records</option><option value="complete">Complete modules</option><option value="partial">Partial modules</option></select></label><button class="btn subtle" :aria-pressed="topTies" @click="topTies=!topTies">{{ topTies?'Show full ranking':'Show all ties at Top 3 cutoff' }}</button><button class="btn subtle" :disabled="page===1" @click="page--">Previous</button><span>{{ total }} records · page {{ page }}</span><button class="btn subtle" :disabled="page*25>=total" @click="page++">Next</button><a :href="download">All scores CSV</a></div><p v-if="error">{{ error }}</p><div class="table-wrap"><table><thead><tr><th>Rank in full population</th><th>Native ID</th><th>Score</th><th>Available modules</th><th>{{ omics==='genome'?'Composition fields / 13':'Resource fields / 5' }}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.entity_id"><td>{{ r.rank }}</td><td><button class="sequence-viz-entity" @click="open(r)">{{ r.entity_id }}</button></td><td>{{ fmt(r.score,7) }}</td><td>{{ r.score_module_coverage }}</td><td>{{ omics==='genome'?r.composition_coverage:r.resource_coverage }}</td></tr></tbody></table></div></section></template>
<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {sequenceGet,sequenceExport} from '../../api/sequenceVisuals';import {number as fmt} from '../../utils/sequenceFormat'
const props=defineProps({speciesId:String,omics:String,scope:String,manifest:Object});const modules=computed(()=>props.omics==='genome'?['island_score','composition_score','dinuc_distance','codon_deviation']:['resource_score','pattern_proxy_score','orf_len_aa','codon_distance','protein_instability_index','max_run_any']);const module=ref(modules.value[0]),coverage=ref('all'),topTies=ref(false),page=ref(1),total=ref(0),rows=ref([]),error=ref('');let seq=0,controller
const download=computed(()=>sequenceExport(props.speciesId,props.omics,{scope:props.scope,artifact_version:props.manifest.artifact_version,source_hash:props.manifest.source_hash,kind:'scores',module:module.value,coverage:coverage.value,...(topTies.value?{top_ties:3}:{})}))
async function load(){const current=++seq;controller?.abort();controller=new AbortController();try{const r=await sequenceGet(props.speciesId,props.omics,'candidates/',{scope:props.scope,artifact_version:props.manifest.artifact_version,source_hash:props.manifest.source_hash,module:module.value,coverage:coverage.value,...(topTies.value?{top_ties:3}:{}),page:page.value,page_size:25},{signal:controller.signal});if(seq!==current)return;rows.value=r.rows;total.value=r.total;error.value=''}catch(e){if(current===seq&&!controller.signal.aborted)error.value=e.message}}
function open(r){window.dispatchEvent(new CustomEvent('stoich-entity-chart-click',{detail:{...r,species_id:props.speciesId}}))}
watch(()=>[props.speciesId,props.omics,props.scope,props.manifest.artifact_version],()=>{module.value=modules.value[0];coverage.value='all';topTies.value=false;page.value=1;load()},{immediate:true});watch([module,coverage,topTies],()=>{page.value=1;load()});watch(page,load);onBeforeUnmount(()=>{seq++;controller?.abort()})
</script>
